-- Generated from reviewed JSON. Apply only after supabase_station_content_v2.sql.
begin;
do $station_release$
declare
  v_release_id uuid;
  v_release_status text;
  v_created_by uuid;
  v_is_admin boolean;
  v_item_count integer;
  v_invalid_day_count integer;
begin
  v_created_by := auth.uid();
  if v_created_by is null then
    select p.id into v_created_by from public.profiles p where p.role = 'admin' order by p.id limit 1;
  end if;
  select exists(select 1 from public.profiles p where p.id = v_created_by and p.role = 'admin') into v_is_admin;
  if v_created_by is null or not coalesce(v_is_admin, false) then
    raise exception 'station_release_import_requires_admin_profile';
  end if;
  insert into public.station_content_releases(version, grade, station_id, title, status, notes, created_by)
  values('g7-st2-2026.1', 7, 'g7_st2', 'Lớp 7 - Trạm 2: Hô hấp và trao đổi ở sinh vật', 'draft', 'Nội dung soạn theo các Bài 25–28, 31 của SGK KHTN 7 Kết nối tri thức; chờ duyệt nội dung và thử giao diện trước khi phát hành.', v_created_by)
  on conflict (version) do update set
    title = case when station_content_releases.status = 'draft' then excluded.title else station_content_releases.title end,
    notes = case when station_content_releases.status = 'draft' then excluded.notes else station_content_releases.notes end,
    updated_at = case when station_content_releases.status = 'draft' then now() else station_content_releases.updated_at end
  returning id into v_release_id;
  select status into v_release_status from public.station_content_releases where id = v_release_id for update;
  if v_release_status <> 'draft' then raise exception 'release_version_is_immutable'; end if;
  delete from public.station_content_items where release_id = v_release_id;
  insert into public.station_content_items(release_id, grade, station_id, day_index, game_index, game_type, title, learning_objective, public_content, answer_key, source_refs)
  values(v_release_id, 7, 'g7_st2', 1, 1, 'quiz', 'Chọn đáp án chính xác', 'Xác định nguyên liệu, sản phẩm và ý nghĩa của hô hấp tế bào.', '{"question":"Hô hấp tế bào có vai trò chủ yếu nào?","options":["Giải phóng năng lượng từ chất hữu cơ","Tạo ánh sáng cho tế bào","Chỉ tạo oxygen","Ngăn mọi quá trình trao đổi chất"],"hint":"Quá trình này cung cấp năng lượng cho hoạt động sống."}'::jsonb, '{"value":"Giải phóng năng lượng từ chất hữu cơ","explanation":"Hô hấp tế bào phân giải chất hữu cơ và giải phóng năng lượng."}'::jsonb, '[{"source":"SGK Khoa học tự nhiên 7 - Kết nối tri thức với cuộc sống","publisher":"Nhà xuất bản Giáo dục Việt Nam","lesson":"Bài 25. Hô hấp tế bào"}]'::jsonb);
  insert into public.station_content_items(release_id, grade, station_id, day_index, game_index, game_type, title, learning_objective, public_content, answer_key, source_refs)
  values(v_release_id, 7, 'g7_st2', 1, 2, 'match', 'Nối khái niệm với đặc điểm', 'Xác định nguyên liệu, sản phẩm và ý nghĩa của hô hấp tế bào.', '{"leftItems":["Chất hữu cơ","Oxygen","Năng lượng"],"rightItems":["Được giải phóng cho hoạt động sống","Tham gia hô hấp tế bào hiếu khí","Nguồn chất được phân giải"],"hint":"Phân biệt vai trò của “Chất hữu cơ” và “Oxygen” trước khi nối. Mô tả của “Chất hữu cơ” bắt đầu bằng “N”."}'::jsonb, '{"value":[{"left":"Chất hữu cơ","right":"Nguồn chất được phân giải"},{"left":"Oxygen","right":"Tham gia hô hấp tế bào hiếu khí"},{"left":"Năng lượng","right":"Được giải phóng cho hoạt động sống"}],"explanation":"Chất hữu cơ: Nguồn chất được phân giải; Oxygen: Tham gia hô hấp tế bào hiếu khí; Năng lượng: Được giải phóng cho hoạt động sống."}'::jsonb, '[{"source":"SGK Khoa học tự nhiên 7 - Kết nối tri thức với cuộc sống","publisher":"Nhà xuất bản Giáo dục Việt Nam","lesson":"Bài 25. Hô hấp tế bào"}]'::jsonb);
  insert into public.station_content_items(release_id, grade, station_id, day_index, game_index, game_type, title, learning_objective, public_content, answer_key, source_refs)
  values(v_release_id, 7, 'g7_st2', 1, 3, 'fill', 'Hoàn thiện kiến thức', 'Xác định nguyên liệu, sản phẩm và ý nghĩa của hô hấp tế bào.', '{"sentence":"Hô hấp tế bào giải phóng [blank] từ chất hữu cơ.","hint":"Xét ngữ cảnh của ô trống trong “Hô hấp tế bào giải phóng [blank] từ chất hữu cơ.”. Từ cần chọn bắt đầu bằng “n” và gồm 2 tiếng."}'::jsonb, '{"value":"năng lượng","explanation":"Từ cần điền là “năng lượng”."}'::jsonb, '[{"source":"SGK Khoa học tự nhiên 7 - Kết nối tri thức với cuộc sống","publisher":"Nhà xuất bản Giáo dục Việt Nam","lesson":"Bài 25. Hô hấp tế bào"}]'::jsonb);
  insert into public.station_content_items(release_id, grade, station_id, day_index, game_index, game_type, title, learning_objective, public_content, answer_key, source_refs)
  values(v_release_id, 7, 'g7_st2', 1, 4, 'category', 'Phân loại đúng nhóm', 'Xác định nguyên liệu, sản phẩm và ý nghĩa của hô hấp tế bào.', '{"categories":["Tham gia hô hấp tế bào hiếu khí","Được tạo ra từ hô hấp tế bào hiếu khí"],"items":["Chất hữu cơ","Oxygen","Carbon dioxide","Nước"],"hint":"Phân biệt hai nhóm “Tham gia hô hấp tế bào hiếu khí” và “Được tạo ra từ hô hấp tế bào hiếu khí” theo đặc điểm của từng mục. “Chất hữu cơ” thuộc nhóm “Tham gia hô hấp tế bào hiếu khí”."}'::jsonb, '{"value":[{"name":"Chất hữu cơ","catIndex":0},{"name":"Oxygen","catIndex":0},{"name":"Carbon dioxide","catIndex":1},{"name":"Nước","catIndex":1}],"explanation":"Chất hữu cơ thuộc nhóm Tham gia hô hấp tế bào hiếu khí; Oxygen thuộc nhóm Tham gia hô hấp tế bào hiếu khí; Carbon dioxide thuộc nhóm Được tạo ra từ hô hấp tế bào hiếu khí; Nước thuộc nhóm Được tạo ra từ hô hấp tế bào hiếu khí."}'::jsonb, '[{"source":"SGK Khoa học tự nhiên 7 - Kết nối tri thức với cuộc sống","publisher":"Nhà xuất bản Giáo dục Việt Nam","lesson":"Bài 25. Hô hấp tế bào"}]'::jsonb);
  insert into public.station_content_items(release_id, grade, station_id, day_index, game_index, game_type, title, learning_objective, public_content, answer_key, source_refs)
  values(v_release_id, 7, 'g7_st2', 1, 5, 'dragdrop', 'Kéo từ hoàn thành câu', 'Xác định nguyên liệu, sản phẩm và ý nghĩa của hô hấp tế bào.', '{"textWithBlanks":"Hô hấp tế bào giúp cung cấp [blank] cho các hoạt động sống.","bankWords":["năng lượng","ánh sáng","diệp lục"],"hint":"Thử từng từ trong kho vào câu “Hô hấp tế bào giúp cung cấp [blank] cho các hoạt động sống.” để tạo phát biểu đúng. Từ cần chọn bắt đầu bằng “n” và gồm 2 tiếng."}'::jsonb, '{"value":"năng lượng","explanation":"Từ đúng là “năng lượng”."}'::jsonb, '[{"source":"SGK Khoa học tự nhiên 7 - Kết nối tri thức với cuộc sống","publisher":"Nhà xuất bản Giáo dục Việt Nam","lesson":"Bài 25. Hô hấp tế bào"}]'::jsonb);
  insert into public.station_content_items(release_id, grade, station_id, day_index, game_index, game_type, title, learning_objective, public_content, answer_key, source_refs)
  values(v_release_id, 7, 'g7_st2', 2, 1, 'quiz', 'Chọn đáp án chính xác', 'Phân biệt hô hấp tế bào với quang hợp qua chiều biến đổi vật chất và năng lượng.', '{"question":"Điểm khác nhau về năng lượng giữa quang hợp và hô hấp tế bào là gì?","options":["Quang hợp tích luỹ, hô hấp tế bào giải phóng năng lượng","Cả hai chỉ hấp thụ năng lượng","Cả hai chỉ tạo ánh sáng","Hô hấp tế bào không liên quan năng lượng"],"hint":"Xét sự tạo chất hữu cơ và phân giải chất hữu cơ."}'::jsonb, '{"value":"Quang hợp tích luỹ, hô hấp tế bào giải phóng năng lượng","explanation":"Quang hợp tích luỹ năng lượng trong chất hữu cơ; hô hấp tế bào giải phóng năng lượng từ chất hữu cơ."}'::jsonb, '[{"source":"SGK Khoa học tự nhiên 7 - Kết nối tri thức với cuộc sống","publisher":"Nhà xuất bản Giáo dục Việt Nam","lesson":"Bài 25. Hô hấp tế bào"}]'::jsonb);
  insert into public.station_content_items(release_id, grade, station_id, day_index, game_index, game_type, title, learning_objective, public_content, answer_key, source_refs)
  values(v_release_id, 7, 'g7_st2', 2, 2, 'match', 'Nối khái niệm với đặc điểm', 'Phân biệt hô hấp tế bào với quang hợp qua chiều biến đổi vật chất và năng lượng.', '{"leftItems":["Quang hợp","Hô hấp tế bào","Thực vật"],"rightItems":["Vừa quang hợp vừa hô hấp tế bào","Phân giải chất hữu cơ để giải phóng năng lượng","Tổng hợp chất hữu cơ nhờ ánh sáng"],"hint":"Phân biệt vai trò của “Quang hợp” và “Hô hấp tế bào” trước khi nối. Mô tả của “Quang hợp” bắt đầu bằng “T”."}'::jsonb, '{"value":[{"left":"Quang hợp","right":"Tổng hợp chất hữu cơ nhờ ánh sáng"},{"left":"Hô hấp tế bào","right":"Phân giải chất hữu cơ để giải phóng năng lượng"},{"left":"Thực vật","right":"Vừa quang hợp vừa hô hấp tế bào"}],"explanation":"Quang hợp: Tổng hợp chất hữu cơ nhờ ánh sáng; Hô hấp tế bào: Phân giải chất hữu cơ để giải phóng năng lượng; Thực vật: Vừa quang hợp vừa hô hấp tế bào."}'::jsonb, '[{"source":"SGK Khoa học tự nhiên 7 - Kết nối tri thức với cuộc sống","publisher":"Nhà xuất bản Giáo dục Việt Nam","lesson":"Bài 25. Hô hấp tế bào"}]'::jsonb);
  insert into public.station_content_items(release_id, grade, station_id, day_index, game_index, game_type, title, learning_objective, public_content, answer_key, source_refs)
  values(v_release_id, 7, 'g7_st2', 2, 3, 'fill', 'Hoàn thiện kiến thức', 'Phân biệt hô hấp tế bào với quang hợp qua chiều biến đổi vật chất và năng lượng.', '{"sentence":"Cây xanh thực hiện cả quang hợp và hô hấp [blank].","hint":"Xét ngữ cảnh của ô trống trong “Cây xanh thực hiện cả quang hợp và hô hấp [blank].”. Từ cần chọn bắt đầu bằng “t” và gồm 2 tiếng."}'::jsonb, '{"value":"tế bào","explanation":"Từ cần điền là “tế bào”."}'::jsonb, '[{"source":"SGK Khoa học tự nhiên 7 - Kết nối tri thức với cuộc sống","publisher":"Nhà xuất bản Giáo dục Việt Nam","lesson":"Bài 25. Hô hấp tế bào"}]'::jsonb);
  insert into public.station_content_items(release_id, grade, station_id, day_index, game_index, game_type, title, learning_objective, public_content, answer_key, source_refs)
  values(v_release_id, 7, 'g7_st2', 2, 4, 'category', 'Phân loại đúng nhóm', 'Phân biệt hô hấp tế bào với quang hợp qua chiều biến đổi vật chất và năng lượng.', '{"categories":["Quang hợp","Hô hấp tế bào"],"items":["Cần ánh sáng để tổng hợp chất hữu cơ","Tích luỹ năng lượng trong chất hữu cơ","Phân giải chất hữu cơ","Giải phóng năng lượng cho tế bào"],"hint":"Phân biệt hai nhóm “Quang hợp” và “Hô hấp tế bào” theo đặc điểm của từng mục. “Cần ánh sáng để tổng hợp chất hữu cơ” thuộc nhóm “Quang hợp”."}'::jsonb, '{"value":[{"name":"Cần ánh sáng để tổng hợp chất hữu cơ","catIndex":0},{"name":"Tích luỹ năng lượng trong chất hữu cơ","catIndex":0},{"name":"Phân giải chất hữu cơ","catIndex":1},{"name":"Giải phóng năng lượng cho tế bào","catIndex":1}],"explanation":"Cần ánh sáng để tổng hợp chất hữu cơ thuộc nhóm Quang hợp; Tích luỹ năng lượng trong chất hữu cơ thuộc nhóm Quang hợp; Phân giải chất hữu cơ thuộc nhóm Hô hấp tế bào; Giải phóng năng lượng cho tế bào thuộc nhóm Hô hấp tế bào."}'::jsonb, '[{"source":"SGK Khoa học tự nhiên 7 - Kết nối tri thức với cuộc sống","publisher":"Nhà xuất bản Giáo dục Việt Nam","lesson":"Bài 25. Hô hấp tế bào"}]'::jsonb);
