  insert into public.station_content_items(release_id, grade, station_id, day_index, game_index, game_type, title, learning_objective, public_content, answer_key, source_refs)
  values(v_release_id, 7, 'g7_st2', 3, 1, 'quiz', 'Chọn đáp án chính xác', 'Nêu các yếu tố ảnh hưởng đến hô hấp tế bào.', '{"question":"Yếu tố nào ảnh hưởng trực tiếp đến hô hấp tế bào?","options":["Nhiệt độ","Tên gọi của chậu","Màu nhãn trên hộp","Độ dài thước kẻ"],"hint":"Hoạt động của enzyme phụ thuộc vào yếu tố này."}'::jsonb, '{"value":"Nhiệt độ","explanation":"Nhiệt độ là một trong các yếu tố ảnh hưởng đến tốc độ hô hấp tế bào."}'::jsonb, '[{"source":"SGK Khoa học tự nhiên 7 - Kết nối tri thức với cuộc sống","publisher":"Nhà xuất bản Giáo dục Việt Nam","lesson":"Bài 26. Một số yếu tố ảnh hưởng đến hô hấp tế bào"}]'::jsonb);
  insert into public.station_content_items(release_id, grade, station_id, day_index, game_index, game_type, title, learning_objective, public_content, answer_key, source_refs)
