  values(v_release_id, 7, 'g7_st2', 10, 5, 'dragdrop', 'Kéo từ hoàn thành câu', 'Giải thích vai trò của hệ tuần hoàn trong vận chuyển các chất ở động vật.', '{"textWithBlanks":"Tim co bóp tạo lực đẩy [blank] lưu thông trong mạch.","bankWords":["máu","nhựa cây","không khí ngoài trời"],"hint":"Thử từng từ trong kho vào câu “Tim co bóp tạo lực đẩy [blank] lưu thông trong mạch.” để tạo phát biểu đúng. Từ cần chọn bắt đầu bằng “m” và gồm 1 tiếng."}'::jsonb, '{"value":"máu","explanation":"Từ đúng là “máu”."}'::jsonb, '[{"source":"SGK Khoa học tự nhiên 7 - Kết nối tri thức với cuộc sống","publisher":"Nhà xuất bản Giáo dục Việt Nam","lesson":"Bài 31. Trao đổi nước và chất dinh dưỡng ở động vật"}]'::jsonb);
  select count(*) into v_item_count from public.station_content_items where release_id = v_release_id;
  if v_item_count <> 50 then
    raise exception 'station_release_import_requires_50_items';
  end if;
  select count(*) into v_invalid_day_count from (
    select day_index
    from public.station_content_items
    where release_id = v_release_id
    group by day_index
    having count(*) <> 5 or count(distinct game_type) <> 5
  ) invalid_days;
  if v_invalid_day_count <> 0 then
    raise exception 'station_release_import_requires_five_unique_games_per_day';
  end if;
end;
